-- =====================================================================
-- BemPlantado. - DDL para o SUPABASE (PostgreSQL)
-- Tradução fiel do ddl_bemplantado.sql (MySQL) do grupo: mesmas 5 tabelas, colunas e chaves.
--
-- Como usar: Supabase > SQL Editor > New query > cole tudo > Run.
-- (Sem CREATE DATABASE / USE: no Supabase o banco já existe; as tabelas ficam no schema "public".)
--
-- Diferenças em relação ao MySQL (só o que o PostgreSQL exige):
--   INT AUTO_INCREMENT  ->  INTEGER GENERATED BY DEFAULT AS IDENTITY
--   DATETIME            ->  TIMESTAMP (sem fuso; as datas ficam em UTC, como o app grava)
--   FLOAT               ->  DOUBLE PRECISION
--   CO2                 ->  "CO2" entre aspas (sem aspas o PostgreSQL guardaria "co2")
-- =====================================================================

CREATE TABLE IF NOT EXISTS usuario (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome        VARCHAR(120),
    cpf         CHAR(11) UNIQUE,
    email       VARCHAR(255) UNIQUE,
    telefone    VARCHAR(20),
    senha_hash  VARCHAR(255),
    criado_em   TIMESTAMP
);

CREATE TABLE IF NOT EXISTS grupo_planta (
    id                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome                 VARCHAR(80) UNIQUE,
    exemplos             VARCHAR(255),
    temp_min             DOUBLE PRECISION,
    temp_max             DOUBLE PRECISION,
    umid_min             DOUBLE PRECISION,
    umid_max             DOUBLE PRECISION,
    intervalo_rega_dias  INTEGER,
    dica_base            TEXT
);

CREATE TABLE IF NOT EXISTS favorito (
    usuario_id  INTEGER,
    grupo_id    INTEGER,
    criado_em   TIMESTAMP,
    PRIMARY KEY (usuario_id, grupo_id),
    FOREIGN KEY (usuario_id) REFERENCES usuario (id),
    FOREIGN KEY (grupo_id)   REFERENCES grupo_planta (id)
);

CREATE TABLE IF NOT EXISTS registro (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    temperature     DOUBLE PRECISION,
    pressure        DOUBLE PRECISION,
    altitude        DOUBLE PRECISION,
    humidity        DOUBLE PRECISION,
    "CO2"           DOUBLE PRECISION,
    particula1      DOUBLE PRECISION,
    particula2      DOUBLE PRECISION,
    registro_tempo  TIMESTAMP UNIQUE
);

CREATE TABLE IF NOT EXISTS insight (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    grupo_id     INTEGER,
    registro_id  INTEGER,
    texto        TEXT,
    modelo       VARCHAR(60),
    criado_em    TIMESTAMP,
    FOREIGN KEY (grupo_id)    REFERENCES grupo_planta (id),
    FOREIGN KEY (registro_id) REFERENCES registro (id)
);

-- ---------------------------------------------------------------------
-- SEGURANÇA (importante no Supabase): toda tabela do schema "public" fica acessível pela API pública
-- (chave "anon") a menos que o RLS esteja ligado. Aqui há CPF, e-mail e senha_hash em "usuario".
-- Com o RLS ligado e SEM políticas, a API pública não lê nem escreve nada; o app Flask continua
-- funcionando porque conecta direto no banco (string de conexão do Postgres), que não passa pelo RLS.
-- ---------------------------------------------------------------------
ALTER TABLE usuario      ENABLE ROW LEVEL SECURITY;
ALTER TABLE grupo_planta ENABLE ROW LEVEL SECURITY;
ALTER TABLE favorito     ENABLE ROW LEVEL SECURITY;
ALTER TABLE registro     ENABLE ROW LEVEL SECURITY;
ALTER TABLE insight      ENABLE ROW LEVEL SECURITY;
